 * Runs the instant-runoff count described by the specification and returns
 * the full list of rounds plus the eventual winner (or null).
 *
 * Each round is { votes: Map<name, count>, exhausted, eliminated, winner },
 * where `votes` holds only the candidates still continuing at that round,
 * and `eliminated`/`winner` are the name eliminated or the winner decided
 * at the end of that round (at most one is set, either may be absent).
 */

function tieBreakEliminate(tied, history, roundCount) {
  let group = tied.slice()
  for (;;) {
    if (group.length === 1) return group[0]
    let diffRound = -1
    for (let r = 0; r < roundCount; r++) {
      const vals = group.map((name) => history.get(name)[r])
      if (!vals.every((v) => v === vals[0])) {
        diffRound = r
        break
      }
    }
    if (diffRound === -1) {
      group.sort()
      return group[group.length - 1]
    }
    const vals = group.map((name) => history.get(name)[diffRound])
    const min = Math.min(...vals)
    group = group.filter((name) => history.get(name)[diffRound] === min)
  }
}

export function countRounds(candidates, ballots) {
  let continuing = new Set(candidates)
  const history = new Map(candidates.map((name) => [name, []]))
  const rounds = []
  let winner = null

  for (;;) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const pick = ballot.candidates.find((name) => continuing.has(name))
      if (pick === undefined) {
        exhausted += ballot.count
      } else {
        votes.set(pick, votes.get(pick) + ballot.count)
      }
    }

    for (const name of continuing) history.get(name).push(votes.get(name))
    const roundCount = history.get(continuing.values().next().value ?? candidates[0]).length

    let active = 0
    for (const v of votes.values()) active += v

    const round = { votes, exhausted }
    rounds.push(round)

    if (active === 0) {
      break
    }

    let majority = null
    for (const [name, count] of votes) {
      if (count * 2 > active) {
        majority = name
        break
      }
    }
    if (majority !== null) {
      round.winner = majority
      winner = majority
      break
    }

    let min = Infinity
    for (const v of votes.values()) if (v < min) min = v
    const tied = [...votes.entries()].filter(([, v]) => v === min).map(([name]) => name)
    const eliminated = tieBreakEliminate(tied, history, roundCount)
    round.eliminated = eliminated
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}
"}

